/* GlobalStone Corporate Website Styles */

/* ===== CSS Variables ===== */
:root {
  /* Colors */
  --navy: #0A1628;
  --navy-light: #162744;
  --white: #ffffff;
  --gray-50: #F8F9FA;
  --gray-100: #E9ECEF;
  --gray-200: #DEE2E6;
  --gray-300: #CED4DA;
  --gray-400: #ADB5BD;
  --gray-500: #6C757D;
  --gray-600: #495057;
  --gray-700: #343A40;
  --gold: #C9A962;
  --gold-light: #D4B978;
  --teal: #0D7377;
  --teal-light: #14919B;

  /* Typography */
  --font-primary: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-serif: 'Playfair Display', Georgia, serif;

  /* Spacing */
  --space-xs: 0.25rem;
  --space-sm: 0.5rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;
  --space-2xl: 3rem;
  --space-3xl: 4rem;
  --space-4xl: 6rem;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(10, 22, 40, 0.05);
  --shadow-md: 0 4px 12px rgba(10, 22, 40, 0.1);
  --shadow-lg: 0 8px 24px rgba(10, 22, 40, 0.12);
  --shadow-xl: 0 16px 48px rgba(10, 22, 40, 0.15);
}

/* ===== Reset & Base ===== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-primary);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--gray-700);
  background-color: var(--white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* ===== Typography ===== */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 600;
  line-height: 1.2;
  color: var(--navy);
}

h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.75rem); }
h3 { font-size: clamp(1.25rem, 3vw, 1.75rem); }
h4 { font-size: 1.25rem; }
h5 { font-size: 1.125rem; }
h6 { font-size: 1rem; }

p {
  margin-bottom: var(--space-md);
}

.text-serif {
  font-family: var(--font-serif);
}

/* ===== Layout ===== */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.container-narrow {
  max-width: 960px;
}

.container-wide {
  max-width: 1440px;
}

.section {
  padding: var(--space-4xl) 0;
}

.section-sm {
  padding: var(--space-2xl) 0;
}

.section-lg {
  padding: var(--space-4xl) 0;
}

/* ===== Grid System ===== */
.grid {
  display: grid;
  gap: var(--space-lg);
}

.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }
.grid-6 { grid-template-columns: repeat(6, 1fr); }

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: 0.75rem 1.5rem;
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  border-radius: 4px;
  transition: all var(--transition-base);
  cursor: pointer;
}

.btn-primary {
  background-color: var(--navy);
  color: var(--white);
  border: 2px solid var(--navy);
}

.btn-primary:hover {
  background-color: var(--navy-light);
  border-color: var(--navy-light);
}

.btn-secondary {
  background-color: transparent;
  color: var(--navy);
  border: 2px solid var(--navy);
}

.btn-secondary:hover {
  background-color: var(--navy);
  color: var(--white);
}

.btn-gold {
  background-color: var(--gold);
  color: var(--navy);
  border: 2px solid var(--gold);
}

.btn-gold:hover {
  background-color: var(--gold-light);
  border-color: var(--gold-light);
}

.btn-text {
  background: none;
  color: var(--navy);
  padding: 0;
  text-transform: none;
  font-weight: 500;
  text-decoration: underline;
  text-underline-offset: 4px;
}

.btn-text:hover {
  color: var(--teal);
}

.btn-text-white {
  color: var(--white);
}

.btn-text-white:hover {
  color: var(--gold);
}

/* ===== Header & Navigation ===== */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background-color: var(--navy);
  transition: background-color var(--transition-base), box-shadow var(--transition-base);
}

.header.scrolled {
  background-color: rgba(10, 22, 40, 0.98);
  box-shadow: var(--shadow-lg);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-md) var(--space-lg);
  max-width: 1440px;
  margin: 0 auto;
}

.logo {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  color: var(--white);
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.logo-icon {
  width: 40px;
  height: 40px;
  background: linear-gradient(135deg, var(--gold), var(--gold-light));
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--navy);
  font-weight: 900;
  font-size: 1.25rem;
}

/* Desktop Navigation */
.nav-desktop {
  display: flex;
  align-items: center;
  gap: var(--space-xl);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
}

.nav-link {
  color: var(--white);
  font-size: 0.875rem;
  font-weight: 500;
  padding: var(--space-sm) 0;
  position: relative;
  transition: color var(--transition-fast);
}

.nav-link:hover {
  color: var(--gold);
}

.nav-link.active {
  color: var(--gold);
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background-color: var(--gold);
  transition: width var(--transition-base);
}

.nav-link:hover::after,
.nav-link.active::after {
  width: 100%;
}

/* Mega Menu */
.nav-item-dropdown {
  position: static;
}

.nav-item-dropdown .nav-link {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
}

.nav-item-dropdown .nav-link::after {
  content: '';
  display: none;
}

.nav-item-dropdown .nav-link svg {
  width: 12px;
  height: 12px;
  transition: transform var(--transition-fast);
}

.nav-item-dropdown:hover .nav-link svg {
  transform: rotate(180deg);
}

/* Mega Menu Dropdown */
.mega-menu {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background-color: var(--white);
  box-shadow: var(--shadow-xl);
  opacity: 0;
  visibility: hidden;
  transform: translateY(10px);
  transition: all var(--transition-base);
  z-index: 100;
  padding: var(--space-2xl);
}

.nav-item-dropdown:hover .mega-menu {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.mega-menu-inner {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: var(--space-3xl);
  max-width: 1280px;
  margin: 0 auto;
}

.mega-menu-section h4 {
  font-family: var(--font-primary);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray-500);
  margin-bottom: var(--space-md);
}

.mega-menu-links {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-md);
}

.mega-menu-link {
  display: flex;
  align-items: flex-start;
  gap: var(--space-sm);
  padding: var(--space-sm);
  border-radius: 4px;
  transition: background-color var(--transition-fast);
}

.mega-menu-link:hover {
  background-color: var(--gray-50);
}

.mega-menu-link-icon {
  width: 32px;
  height: 32px;
  background-color: var(--navy);
  color: var(--white);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.mega-menu-link-text h5 {
  font-family: var(--font-primary);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 2px;
}

.mega-menu-link-text p {
  font-size: 0.75rem;
  color: var(--gray-500);
  margin: 0;
  line-height: 1.4;
}

.mega-menu-cta {
  background-color: var(--gray-50);
  padding: var(--space-lg);
  border-radius: 8px;
  text-align: center;
}

.mega-menu-cta h5 {
  font-family: var(--font-primary);
  font-size: 1rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: var(--space-sm);
}

.mega-menu-cta p {
  font-size: 0.875rem;
  color: var(--gray-600);
  margin-bottom: var(--space-md);
}

/* Mobile Navigation Toggle */
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-sm);
  cursor: pointer;
}

.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background-color: var(--white);
  transition: all var(--transition-fast);
}

/* Mobile Navigation */
.nav-mobile {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--navy);
  overflow-y: auto;
  z-index: 999;
}

.nav-mobile.active {
  display: block;
}

.nav-mobile-section {
  border-bottom: 1px solid var(--navy-light);
}

.nav-mobile-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-lg);
  color: var(--white);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
}

.nav-mobile-section-header svg {
  width: 20px;
  height: 20px;
  transition: transform var(--transition-fast);
}

.nav-mobile-section.active .nav-mobile-section-header svg {
  transform: rotate(180deg);
}

.nav-mobile-section-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-base);
}

.nav-mobile-section.active .nav-mobile-section-content {
  max-height: 500px;
}

.nav-mobile-link {
  display: block;
  padding: var(--space-md) var(--space-lg);
  padding-left: var(--space-2xl);
  color: var(--gray-300);
  font-size: 0.875rem;
  transition: color var(--transition-fast);
}

.nav-mobile-link:hover {
  color: var(--gold);
}

/* ===== Hero Section ===== */
.hero {
  position: relative;
  min-height: 80vh;
  display: flex;
  align-items: center;
  background-color: var(--navy);
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-light) 100%);
}

.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><defs><pattern id="grid" width="10" height="10" patternUnits="userSpaceOnUse"><path d="M 10 0 L 0 0 0 10" fill="none" stroke="rgba(255,255,255,0.03)" stroke-width="0.5"/></pattern></defs><rect fill="url(%23grid)" width="100" height="100"/></svg>');
  opacity: 0.5;
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 800px;
  padding: var(--space-4xl) var(--space-lg);
}

.hero-badge {
  display: inline-block;
  background-color: rgba(201, 169, 98, 0.2);
  color: var(--gold);
  padding: var(--space-xs) var(--space-md);
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: var(--space-lg);
}

.hero h1 {
  color: var(--white);
  margin-bottom: var(--space-lg);
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--gray-300);
  margin-bottom: var(--space-xl);
  max-width: 600px;
}

.hero-actions {
  display: flex;
  gap: var(--space-md);
  flex-wrap: wrap;
}

/* Hero - Page Header Variant */
.hero-page {
  min-height: 50vh;
  text-align: center;
}

.hero-page .hero-content {
  max-width: 900px;
  margin: 0 auto;
}

/* ===== Featured Insights ===== */
.featured-insights {
  background-color: var(--gray-50);
}

.featured-insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
  margin-top: var(--space-2xl);
}

.insight-card {
  background-color: var(--white);
  border-radius: 8px;
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
}

.insight-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.insight-card-image {
  height: 160px;
  background-color: var(--gray-200);
  background-size: cover;
  background-position: center;
  position: relative;
}

.insight-card-image::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, transparent 50%, rgba(10, 22, 40, 0.3));
}

.insight-card-tag {
  position: absolute;
  top: var(--space-md);
  left: var(--space-md);
  background-color: var(--navy);
  color: var(--white);
  padding: var(--space-xs) var(--space-sm);
  font-size: 0.625rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-radius: 2px;
}

.insight-card-content {
  padding: var(--space-lg);
}

.insight-card-type {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: var(--space-sm);
}

.insight-card-title {
  font-family: var(--font-primary);
  font-size: 1rem;
  font-weight: 600;
  color: var(--navy);
  line-height: 1.4;
  margin-bottom: var(--space-sm);
}

.insight-card:hover .insight-card-title {
  color: var(--teal);
}

.insight-card-link {
  display: inline-flex;
  align-items: center;
  gap: var(--space-xs);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--navy);
}

.insight-card-link svg {
  width: 16px;
  height: 16px;
  transition: transform var(--transition-fast);
}

.insight-card:hover .insight-card-link svg {
  transform: translateX(4px);
}

/* ===== Announcement Banner ===== */
.announcement-banner {
  background: linear-gradient(135deg, var(--teal), var(--teal-light));
  padding: var(--space-lg) 0;
  text-align: center;
}

.announcement-banner p {
  color: var(--white);
  font-size: 1rem;
  margin-bottom: var(--space-md);
}

.announcement-banner .btn {
  background-color: var(--white);
  color: var(--teal);
  border-color: var(--white);
}

.announcement-banner .btn:hover {
  background-color: var(--gold);
  border-color: var(--gold);
  color: var(--navy);
}

/* ===== About Statement ===== */
.about-statement {
  background-color: var(--white);
  text-align: center;
}

.about-statement h2 {
  margin-bottom: var(--space-lg);
}

.about-statement p {
  max-width: 800px;
  margin: 0 auto var(--space-xl);
  font-size: 1.125rem;
  color: var(--gray-600);
}

/* ===== What We Do Tabs ===== */
.what-we-do {
  background-color: var(--navy);
}

.what-we-do .section-header {
  text-align: center;
  margin-bottom: var(--space-2xl);
}

.what-we-do .section-header h2 {
  color: var(--white);
}

.what-we-do-tabs {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: var(--space-2xl);
  max-width: 1000px;
  margin: 0 auto;
}

.what-we-do-tab-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.what-we-do-tab-btn {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  padding: var(--space-md) var(--space-lg);
  background: none;
  border: none;
  border-left: 3px solid transparent;
  color: var(--gray-400);
  font-size: 1rem;
  font-weight: 500;
  text-align: left;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.what-we-do-tab-btn:hover {
  color: var(--white);
}

.what-we-do-tab-btn.active {
  background-color: rgba(255, 255, 255, 0.05);
  border-left-color: var(--gold);
  color: var(--white);
}

.what-we-do-tab-btn svg {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
}

.what-we-do-tab-content {
  background-color: rgba(255, 255, 255, 0.05);
  border-radius: 8px;
  padding: var(--space-2xl);
  display: none;
}

.what-we-do-tab-content.active {
  display: block;
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.what-we-do-tab-content h3 {
  color: var(--white);
  margin-bottom: var(--space-md);
}

.what-we-do-tab-content p {
  color: var(--gray-300);
  margin-bottom: var(--space-lg);
  line-height: 1.7;
}

.what-we-do-tab-content .btn {
  margin-top: var(--space-md);
}

/* ===== Newsletter Section ===== */
.newsletter {
  background: linear-gradient(135deg, var(--navy-light), var(--navy));
  text-align: center;
  position: relative;
  overflow: hidden;
}

.newsletter::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(circle at 30% 30%, rgba(201, 169, 98, 0.1) 0%, transparent 50%);
}

.newsletter-content {
  position: relative;
  z-index: 1;
}

.newsletter h2 {
  color: var(--white);
  margin-bottom: var(--space-md);
}

.newsletter p {
  color: var(--gray-300);
  max-width: 500px;
  margin: 0 auto var(--space-xl);
}

.newsletter-form {
  display: flex;
  gap: var(--space-md);
  max-width: 500px;
  margin: 0 auto;
}

.newsletter-input {
  flex: 1;
  padding: var(--space-md) var(--space-lg);
  background-color: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 4px;
  color: var(--white);
  font-size: 1rem;
}

.newsletter-input::placeholder {
  color: var(--gray-400);
}

.newsletter-input:focus {
  outline: none;
  border-color: var(--gold);
}

/* ===== Latest Insights ===== */
.latest-insights {
  background-color: var(--white);
}

.latest-insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
  margin-top: var(--space-2xl);
}

.latest-insight-card {
  background-color: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  overflow: hidden;
  transition: all var(--transition-base);
}

.latest-insight-card:hover {
  border-color: var(--gold);
  box-shadow: var(--shadow-md);
}

.latest-insight-card-image {
  height: 180px;
  background-color: var(--gray-200);
  background-size: cover;
  background-position: center;
  position: relative;
}

.latest-insight-card-image .insight-card-tag {
  background-color: var(--gold);
  color: var(--navy);
}

.latest-insight-card-content {
  padding: var(--space-lg);
}

.latest-insight-card-meta {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  margin-bottom: var(--space-sm);
}

.latest-insight-card-type {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--teal);
}

.latest-insight-card-date {
  font-size: 0.75rem;
  color: var(--gray-500);
}

.latest-insight-card h4 {
  font-family: var(--font-primary);
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--navy);
  line-height: 1.4;
  margin-bottom: var(--space-md);
}

.latest-insight-card:hover h4 {
  color: var(--teal);
}

/* ===== Our Commitment ===== */
.our-commitment {
  background-color: var(--gray-50);
}

.our-commitment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-lg);
  margin-top: var(--space-2xl);
}

.commitment-card {
  background-color: var(--white);
  border-radius: 8px;
  padding: var(--space-xl);
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
}

.commitment-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.commitment-card-icon {
  width: 56px;
  height: 56px;
  background: linear-gradient(135deg, var(--navy), var(--navy-light));
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-lg);
}

.commitment-card-icon svg {
  width: 28px;
  height: 28px;
  color: var(--gold);
}

.commitment-card h4 {
  font-family: var(--font-primary);
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: var(--space-sm);
}

.commitment-card p {
  font-size: 0.875rem;
  color: var(--gray-600);
  margin-bottom: var(--space-md);
  line-height: 1.6;
}

/* ===== Services Page ===== */
.services-overview {
  padding: var(--space-4xl) 0;
}

.services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
  margin-top: var(--space-2xl);
}

.service-card {
  background-color: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  padding: var(--space-xl);
  transition: all var(--transition-base);
}

.service-card:hover {
  border-color: var(--gold);
  box-shadow: var(--shadow-lg);
}

.service-card-icon {
  width: 64px;
  height: 64px;
  background: linear-gradient(135deg, var(--navy), var(--navy-light));
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-lg);
}

.service-card-icon svg {
  width: 32px;
  height: 32px;
  color: var(--gold);
}

.service-card h3 {
  margin-bottom: var(--space-md);
}

.service-card p {
  font-size: 0.9375rem;
  color: var(--gray-600);
  margin-bottom: var(--space-lg);
}

/* ===== Capabilities Grid ===== */
.capabilities-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
  margin-top: var(--space-2xl);
}

.capability-card {
  background-color: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  padding: var(--space-xl);
  transition: all var(--transition-base);
}

.capability-card:hover {
  border-color: var(--teal);
  box-shadow: var(--shadow-md);
}

.capability-card h4 {
  font-family: var(--font-primary);
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: var(--space-sm);
}

.capability-card p {
  font-size: 0.875rem;
  color: var(--gray-600);
  margin-bottom: var(--space-md);
}

/* ===== Featured Partners Carousel ===== */
.featured-partners {
  background-color: var(--gray-50);
  overflow: hidden;
}

.carousel {
  position: relative;
  margin-top: var(--space-2xl);
}

.carousel-track {
  display: flex;
  gap: var(--space-lg);
  transition: transform 0.5s ease;
}

.carousel-slide {
  flex: 0 0 calc(33.333% - var(--space-lg));
  min-width: 300px;
}

.partner-card {
  background-color: var(--white);
  border-radius: 8px;
  padding: var(--space-xl);
  box-shadow: var(--shadow-sm);
  text-align: center;
}

.partner-logo {
  height: 60px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-md);
  color: var(--navy);
  font-weight: 700;
  font-size: 1.25rem;
}

.partner-card h4 {
  font-family: var(--font-primary);
  font-size: 1rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: var(--space-sm);
}

.partner-card p {
  font-size: 0.875rem;
  color: var(--gray-600);
}

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: var(--space-md);
  margin-top: var(--space-xl);
}

.carousel-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background-color: var(--white);
  border: 1px solid var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.carousel-btn:hover {
  background-color: var(--navy);
  border-color: var(--navy);
  color: var(--white);
}

.carousel-btn svg {
  width: 20px;
  height: 20px;
}

/* ===== Testimonial ===== */
.testimonial {
  background-color: var(--navy);
  text-align: center;
}

.testimonial blockquote {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 3vw, 1.75rem);
  color: var(--white);
  max-width: 800px;
  margin: 0 auto var(--space-xl);
  line-height: 1.6;
  font-style: italic;
}

.testimonial cite {
  display: block;
  font-family: var(--font-primary);
  font-style: normal;
  font-size: 1rem;
  color: var(--gold);
}

.testimonial cite strong {
  display: block;
  color: var(--white);
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

/* ===== Deal Flow CTA ===== */
.deal-flow-cta {
  background: linear-gradient(135deg, var(--gold), var(--gold-light));
  text-align: center;
}

.deal-flow-cta h2 {
  color: var(--navy);
  margin-bottom: var(--space-md);
}

.deal-flow-cta p {
  color: var(--navy);
  opacity: 0.8;
  max-width: 600px;
  margin: 0 auto var(--space-xl);
}

.deal-flow-cta .btn {
  background-color: var(--navy);
  color: var(--white);
  border-color: var(--navy);
}

.deal-flow-cta .btn:hover {
  background-color: var(--navy-light);
}

/* ===== Featured Topics Sidebar ===== */
.featured-topics {
  background-color: var(--gray-50);
}

.topics-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
  margin-top: var(--space-md);
}

.topic-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-md) var(--space-lg);
  background-color: var(--white);
  border-radius: 4px;
  font-weight: 500;
  color: var(--navy);
  transition: all var(--transition-fast);
}

.topic-link:hover {
  background-color: var(--navy);
  color: var(--white);
}

.topic-link svg {
  width: 16px;
  height: 16px;
  opacity: 0;
  transform: translateX(-8px);
  transition: all var(--transition-fast);
}

.topic-link:hover svg {
  opacity: 1;
  transform: translateX(0);
}

/* ===== Property Types CTA ===== */
.property-types-cta {
  background-color: var(--white);
}

.property-types-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-md);
  margin-top: var(--space-xl);
}

.property-type-card {
  background-color: var(--gray-50);
  border-radius: 8px;
  padding: var(--space-lg);
  text-align: center;
  transition: all var(--transition-base);
  cursor: pointer;
}

.property-type-card:hover {
  background-color: var(--navy);
  transform: translateY(-4px);
}

.property-type-card:hover svg {
  color: var(--gold);
}

.property-type-card svg {
  width: 40px;
  height: 40px;
  color: var(--navy);
  margin-bottom: var(--space-sm);
  transition: color var(--transition-fast);
}

.property-type-card h5 {
  font-family: var(--font-primary);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--navy);
  transition: color var(--transition-fast);
}

.property-type-card:hover h5 {
  color: var(--white);
}

/* ===== Related Services ===== */
.related-services {
  background-color: var(--gray-50);
}

.related-services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
  margin-top: var(--space-xl);
}

.related-service-card {
  background-color: var(--white);
  border-radius: 8px;
  padding: var(--space-lg);
  display: flex;
  align-items: flex-start;
  gap: var(--space-md);
  transition: all var(--transition-base);
}

.related-service-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.related-service-icon {
  width: 48px;
  height: 48px;
  background-color: var(--navy);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.related-service-icon svg {
  width: 24px;
  height: 24px;
  color: var(--gold);
}

.related-service-content h5 {
  font-family: var(--font-primary);
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: var(--space-xs);
}

.related-service-content p {
  font-size: 0.8125rem;
  color: var(--gray-500);
  margin: 0;
  line-height: 1.5;
}

/* ===== Related Insights ===== */
.related-insights {
  background-color: var(--white);
}

.related-insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
  margin-top: var(--space-xl);
}

/* ===== Design Build Capabilities ===== */
.design-build-capabilities {
  padding: var(--space-4xl) 0;
}

.capability-highlight {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-xl);
  margin-top: var(--space-2xl);
}

.capability-highlight-card {
  background-color: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  padding: var(--space-2xl);
  position: relative;
  overflow: hidden;
}

.capability-highlight-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 4px;
  height: 100%;
  background: linear-gradient(to bottom, var(--gold), var(--teal));
}

.capability-highlight-card h3 {
  margin-bottom: var(--space-md);
}

.capability-highlight-card p {
  color: var(--gray-600);
  margin-bottom: var(--space-lg);
}

/* ===== Partnership Highlight ===== */
.partnership-highlight {
  background-color: var(--gray-50);
  text-align: center;
}

.partnership-highlight-content {
  max-width: 800px;
  margin: 0 auto;
}

.partnership-highlight-icon {
  width: 80px;
  height: 80px;
  background: linear-gradient(135deg, var(--navy), var(--navy-light));
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-xl);
}

.partnership-highlight-icon svg {
  width: 40px;
  height: 40px;
  color: var(--gold);
}

.partnership-highlight h2 {
  margin-bottom: var(--space-lg);
}

.partnership-highlight p {
  font-size: 1.125rem;
  color: var(--gray-600);
  margin-bottom: var(--space-md);
}

.partnership-stats {
  display: flex;
  justify-content: center;
  gap: var(--space-3xl);
  margin-top: var(--space-xl);
}

.partnership-stat {
  text-align: center;
}

.partnership-stat-value {
  font-family: var(--font-serif);
  font-size: 3rem;
  font-weight: 700;
  color: var(--navy);
  line-height: 1;
}

.partnership-stat-label {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-top: var(--space-xs);
}

/* ===== Footer ===== */
.footer {
  background-color: var(--navy);
  color: var(--white);
  padding: var(--space-4xl) 0 var(--space-xl);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: var(--space-2xl);
  margin-bottom: var(--space-3xl);
}

.footer-brand p {
  color: var(--gray-400);
  font-size: 0.875rem;
  max-width: 300px;
  margin-top: var(--space-lg);
}

.footer-col h5 {
  font-family: var(--font-primary);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray-400);
  margin-bottom: var(--space-lg);
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.footer-col a {
  font-size: 0.875rem;
  color: var(--gray-300);
  transition: color var(--transition-fast);
}

.footer-col a:hover {
  color: var(--gold);
}

.footer-bottom {
  border-top: 1px solid var(--navy-light);
  padding-top: var(--space-xl);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-md);
}

.footer-legal {
  display: flex;
  gap: var(--space-lg);
}

.footer-legal a {
  font-size: 0.8125rem;
  color: var(--gray-400);
}

.footer-legal a:hover {
  color: var(--gold);
}

.footer-copyright {
  font-size: 0.8125rem;
  color: var(--gray-500);
}

/* ===== Utility Classes ===== */
.text-center { text-align: center; }
.text-left { text-align: left; }
.text-right { text-align: right; }

.mt-sm { margin-top: var(--space-sm); }
.mt-md { margin-top: var(--space-md); }
.mt-lg { margin-top: var(--space-lg); }
.mt-xl { margin-top: var(--space-xl); }
.mt-2xl { margin-top: var(--space-2xl); }

.mb-sm { margin-bottom: var(--space-sm); }
.mb-md { margin-bottom: var(--space-md); }
.mb-lg { margin-bottom: var(--space-lg); }
.mb-xl { margin-bottom: var(--space-xl); }
.mb-2xl { margin-bottom: var(--space-2xl); }

.bg-navy { background-color: var(--navy); }
.bg-gray { background-color: var(--gray-50); }
.bg-white { background-color: var(--white); }

.text-white { color: var(--white); }
.text-gold { color: var(--gold); }
.text-teal { color: var(--teal); }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-6 { grid-template-columns: repeat(3, 1fr); }

  .services-grid { grid-template-columns: repeat(2, 1fr); }
  .capabilities-grid { grid-template-columns: repeat(2, 1fr); }
  .our-commitment-grid { grid-template-columns: repeat(2, 1fr); }
  .property-types-grid { grid-template-columns: repeat(3, 1fr); }

  .footer-grid { grid-template-columns: repeat(3, 1fr); }

  .mega-menu-inner { grid-template-columns: 1fr; }
  .mega-menu-links { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .nav-desktop { display: none; }
  .nav-toggle { display: flex; }

  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }

  .featured-insights-grid { grid-template-columns: 1fr; }
  .latest-insights-grid { grid-template-columns: 1fr; }
  .services-grid { grid-template-columns: 1fr; }
  .capabilities-grid { grid-template-columns: 1fr; }
  .our-commitment-grid { grid-template-columns: 1fr; }
  .property-types-grid { grid-template-columns: repeat(2, 1fr); }
  .related-services-grid { grid-template-columns: 1fr; }
  .related-insights-grid { grid-template-columns: 1fr; }
  .capability-highlight { grid-template-columns: 1fr; }

  .what-we-do-tabs {
    grid-template-columns: 1fr;
  }

  .what-we-do-tab-list {
    flex-direction: row;
    overflow-x: auto;
    gap: var(--space-sm);
    padding-bottom: var(--space-md);
  }

  .what-we-do-tab-btn {
    flex-shrink: 0;
    border-left: none;
    border-bottom: 3px solid transparent;
  }

  .what-we-do-tab-btn.active {
    border-left: none;
    border-bottom-color: var(--gold);
  }

  .newsletter-form { flex-direction: column; }

  .partnership-stats {
    flex-direction: column;
    gap: var(--space-xl);
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: var(--space-xl);
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }

  .footer-legal {
    flex-wrap: wrap;
    justify-content: center;
  }

  .hero { min-height: 70vh; }
  .hero-page { min-height: 40vh; }
}

@media (max-width: 480px) {
  .container { padding: 0 var(--space-md); }
  .section { padding: var(--space-2xl) 0; }
  .property-types-grid { grid-template-columns: 1fr; }
}

/* GlobalStone Corporate Website Styles */

/* ===== CSS Variables ===== */
:root {
  /* Colors */
  --navy: #0A1628;
  --navy-light: #162744;
  --white: #ffffff;
  --gray-50: #F8F9FA;
  --gray-100: #E9ECEF;
  --gray-200: #DEE2E6;
  --gray-300: #CED4DA;
  --gray-400: #ADB5BD;
  --gray-500: #6C757D;
  --gray-600: #495057;
  --gray-700: #343A40;
  --gold: #C9A962;
  --gold-light: #D4B978;
  --teal: #0D7377;
  --teal-light: #14919B;

  /* Typography */
  --font-primary: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-serif: 'Playfair Display', Georgia, serif;

  /* Spacing */
  --space-xs: 0.25rem;
  --space-sm: 0.5rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;
  --space-2xl: 3rem;
  --space-3xl: 4rem;
  --space-4xl: 6rem;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(10, 22, 40, 0.05);
  --shadow-md: 0 4px 12px rgba(10, 22, 40, 0.1);
  --shadow-lg: 0 8px 24px rgba(10, 22, 40, 0.12);
  --shadow-xl: 0 16px 48px rgba(10, 22, 40, 0.15);
}

/* ===== Reset & Base ===== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-primary);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--gray-700);
  background-color: var(--white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* ===== Typography ===== */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 600;
  line-height: 1.2;
  color: var(--navy);
}

h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.75rem); }
h3 { font-size: clamp(1.25rem, 3vw, 1.75rem); }
h4 { font-size: 1.25rem; }
h5 { font-size: 1.125rem; }
h6 { font-size: 1rem; }

p {
  margin-bottom: var(--space-md);
}

.text-serif {
  font-family: var(--font-serif);
}

/* ===== Layout ===== */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.container-narrow {
  max-width: 960px;
}

.container-wide {
  max-width: 1440px;
}

.section {
  padding: var(--space-4xl) 0;
}

.section-sm {
  padding: var(--space-2xl) 0;
}

.section-lg {
  padding: var(--space-4xl) 0;
}

/* ===== Grid System ===== */
.grid {
  display: grid;
  gap: var(--space-lg);
}

.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }
.grid-6 { grid-template-columns: repeat(6, 1fr); }

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: 0.75rem 1.5rem;
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  border-radius: 4px;
  transition: all var(--transition-base);
  cursor: pointer;
}

.btn-primary {
  background-color: var(--navy);
  color: var(--white);
  border: 2px solid var(--navy);
}

.btn-primary:hover {
  background-color: var(--navy-light);
  border-color: var(--navy-light);
}

.btn-secondary {
  background-color: transparent;
  color: var(--navy);
  border: 2px solid var(--navy);
}

.btn-secondary:hover {
  background-color: var(--navy);
  color: var(--white);
}

.btn-gold {
  background-color: var(--gold);
  color: var(--navy);
  border: 2px solid var(--gold);
}

.btn-gold:hover {
  background-color: var(--gold-light);
  border-color: var(--gold-light);
}

.btn-text {
  background: none;
  color: var(--navy);
  padding: 0;
  text-transform: none;
  font-weight: 500;
  text-decoration: underline;
  text-underline-offset: 4px;
}

.btn-text:hover {
  color: var(--teal);
}

.btn-text-white {
  color: var(--white);
}

.btn-text-white:hover {
  color: var(--gold);
}

/* ===== Header & Navigation ===== */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background-color: var(--navy);
  transition: background-color var(--transition-base), box-shadow var(--transition-base);
}

.header.scrolled {
  background-color: rgba(10, 22, 40, 0.98);
  box-shadow: var(--shadow-lg);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-md) var(--space-lg);
  max-width: 1440px;
  margin: 0 auto;
}

.logo {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  color: var(--white);
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.logo-icon {
  width: 40px;
  height: 40px;
  background: linear-gradient(135deg, var(--gold), var(--gold-light));
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--navy);
  font-weight: 900;
  font-size: 1.25rem;
}

/* Desktop Navigation */
.nav-desktop {
  display: flex;
  align-items: center;
  gap: var(--space-xl);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
}

.nav-link {
  color: var(--white);
  font-size: 0.875rem;
  font-weight: 500;
  padding: var(--space-sm) 0;
  position: relative;
  transition: color var(--transition-fast);
}

.nav-link:hover {
  color: var(--gold);
}

.nav-link.active {
  color: var(--gold);
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background-color: var(--gold);
  transition: width var(--transition-base);
}

.nav-link:hover::after,
.nav-link.active::after {
  width: 100%;
}

/* Mega Menu */
.nav-item-dropdown {
  position: static;
}

.nav-item-dropdown .nav-link {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
}

.nav-item-dropdown .nav-link::after {
  content: '';
  display: none;
}

.nav-item-dropdown .nav-link svg {
  width: 12px;
  height: 12px;
  transition: transform var(--transition-fast);
}

.nav-item-dropdown:hover .nav-link svg {
  transform: rotate(180deg);
}

/* Mega Menu Dropdown */
.mega-menu {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background-color: var(--white);
  box-shadow: var(--shadow-xl);
  opacity: 0;
  visibility: hidden;
  transform: translateY(10px);
  transition: all var(--transition-base);
  z-index: 100;
  padding: var(--space-2xl);
}

.nav-item-dropdown:hover .mega-menu {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.mega-menu-inner {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: var(--space-3xl);
  max-width: 1280px;
  margin: 0 auto;
}

.mega-menu-section h4 {
  font-family: var(--font-primary);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray-500);
  margin-bottom: var(--space-md);
}

.mega-menu-links {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-md);
}

.mega-menu-link {
  display: flex;
  align-items: flex-start;
  gap: var(--space-sm);
  padding: var(--space-sm);
  border-radius: 4px;
  transition: background-color var(--transition-fast);
}

.mega-menu-link:hover {
  background-color: var(--gray-50);
}

.mega-menu-link-icon {
  width: 32px;
  height: 32px;
  background-color: var(--navy);
  color: var(--white);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.mega-menu-link-text h5 {
  font-family: var(--font-primary);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 2px;
}

.mega-menu-link-text p {
  font-size: 0.75rem;
  color: var(--gray-500);
  margin: 0;
  line-height: 1.4;
}

.mega-menu-cta {
  background-color: var(--gray-50);
  padding: var(--space-lg);
  border-radius: 8px;
  text-align: center;
}

.mega-menu-cta h5 {
  font-family: var(--font-primary);
  font-size: 1rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: var(--space-sm);
}

.mega-menu-cta p {
  font-size: 0.875rem;
  color: var(--gray-600);
  margin-bottom: var(--space-md);
}

/* Mobile Navigation Toggle */
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-sm);
  cursor: pointer;
}

.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background-color: var(--white);
  transition: all var(--transition-fast);
}

/* Mobile Navigation */
.nav-mobile {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--navy);
  overflow-y: auto;
  z-index: 999;
}

.nav-mobile.active {
  display: block;
}

.nav-mobile-section {
  border-bottom: 1px solid var(--navy-light);
}

.nav-mobile-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-lg);
  color: var(--white);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
}

.nav-mobile-section-header svg {
  width: 20px;
  height: 20px;
  transition: transform var(--transition-fast);
}

.nav-mobile-section.active .nav-mobile-section-header svg {
  transform: rotate(180deg);
}

.nav-mobile-section-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-base);
}

.nav-mobile-section.active .nav-mobile-section-content {
  max-height: 500px;
}

.nav-mobile-link {
  display: block;
  padding: var(--space-md) var(--space-lg);
  padding-left: var(--space-2xl);
  color: var(--gray-300);
  font-size: 0.875rem;
  transition: color var(--transition-fast);
}

.nav-mobile-link:hover {
  color: var(--gold);
}

/* ===== Hero Section ===== */
.hero {
  position: relative;
  min-height: 80vh;
  display: flex;
  align-items: center;
  background-color: var(--navy);
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-light) 100%);
}

.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><defs><pattern id="grid" width="10" height="10" patternUnits="userSpaceOnUse"><path d="M 10 0 L 0 0 0 10" fill="none" stroke="rgba(255,255,255,0.03)" stroke-width="0.5"/></pattern></defs><rect fill="url(%23grid)" width="100" height="100"/></svg>');
  opacity: 0.5;
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 800px;
  padding: var(--space-4xl) var(--space-lg);
}

.hero-badge {
  display: inline-block;
  background-color: rgba(201, 169, 98, 0.2);
  color: var(--gold);
  padding: var(--space-xs) var(--space-md);
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: var(--space-lg);
}

.hero h1 {
  color: var(--white);
  margin-bottom: var(--space-lg);
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--gray-300);
  margin-bottom: var(--space-xl);
  max-width: 600px;
}

.hero-actions {
  display: flex;
  gap: var(--space-md);
  flex-wrap: wrap;
}

/* Hero - Page Header Variant */
.hero-page {
  min-height: 50vh;
  text-align: center;
}

.hero-page .hero-content {
  max-width: 900px;
  margin: 0 auto;
}

/* ===== Featured Insights ===== */
.featured-insights {
  background-color: var(--gray-50);
}

.featured-insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
  margin-top: var(--space-2xl);
}

.insight-card {
  background-color: var(--white);
  border-radius: 8px;
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
}

.insight-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.insight-card-image {
  height: 160px;
  background-color: var(--gray-200);
  background-size: cover;
  background-position: center;
  position: relative;
}

.insight-card-image::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, transparent 50%, rgba(10, 22, 40, 0.3));
}

.insight-card-tag {
  position: absolute;
  top: var(--space-md);
  left: var(--space-md);
  background-color: var(--navy);
  color: var(--white);
  padding: var(--space-xs) var(--space-sm);
  font-size: 0.625rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-radius: 2px;
}

.insight-card-content {
  padding: var(--space-lg);
}

.insight-card-type {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: var(--space-sm);
}

.insight-card-title {
  font-family: var(--font-primary);
  font-size: 1rem;
  font-weight: 600;
  color: var(--navy);
  line-height: 1.4;
  margin-bottom: var(--space-sm);
}

.insight-card:hover .insight-card-title {
  color: var(--teal);
}

.insight-card-link {
  display: inline-flex;
  align-items: center;
  gap: var(--space-xs);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--navy);
}

.insight-card-link svg {
  width: 16px;
  height: 16px;
  transition: transform var(--transition-fast);
}

.insight-card:hover .insight-card-link svg {
  transform: translateX(4px);
}

/* ===== Announcement Banner ===== */
.announcement-banner {
  background: linear-gradient(135deg, var(--teal), var(--teal-light));
  padding: var(--space-lg) 0;
  text-align: center;
}

.announcement-banner p {
  color: var(--white);
  font-size: 1rem;
  margin-bottom: var(--space-md);
}

.announcement-banner .btn {
  background-color: var(--white);
  color: var(--teal);
  border-color: var(--white);
}

.announcement-banner .btn:hover {
  background-color: var(--gold);
  border-color: var(--gold);
  color: var(--navy);
}

/* ===== About Statement ===== */
.about-statement {
  background-color: var(--white);
  text-align: center;
}

.about-statement h2 {
  margin-bottom: var(--space-lg);
}

.about-statement p {
  max-width: 800px;
  margin: 0 auto var(--space-xl);
  font-size: 1.125rem;
  color: var(--gray-600);
}

/* ===== What We Do Tabs ===== */
.what-we-do {
  background-color: var(--navy);
}

.what-we-do .section-header {
  text-align: center;
  margin-bottom: var(--space-2xl);
}

.what-we-do .section-header h2 {
  color: var(--white);
}

.what-we-do-tabs {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: var(--space-2xl);
  max-width: 1000px;
  margin: 0 auto;
}

.what-we-do-tab-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.what-we-do-tab-btn {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  padding: var(--space-md) var(--space-lg);
  background: none;
  border: none;
  border-left: 3px solid transparent;
  color: var(--gray-400);
  font-size: 1rem;
  font-weight: 500;
  text-align: left;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.what-we-do-tab-btn:hover {
  color: var(--white);
}

.what-we-do-tab-btn.active {
  background-color: rgba(255, 255, 255, 0.05);
  border-left-color: var(--gold);
  color: var(--white);
}

.what-we-do-tab-btn svg {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
}

.what-we-do-tab-content {
  background-color: rgba(255, 255, 255, 0.05);
  border-radius: 8px;
  padding: var(--space-2xl);
  display: none;
}

.what-we-do-tab-content.active {
  display: block;
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.what-we-do-tab-content h3 {
  color: var(--white);
  margin-bottom: var(--space-md);
}

.what-we-do-tab-content p {
  color: var(--gray-300);
  margin-bottom: var(--space-lg);
  line-height: 1.7;
}

.what-we-do-tab-content .btn {
  margin-top: var(--space-md);
}

/* ===== Newsletter Section ===== */
.newsletter {
  background: linear-gradient(135deg, var(--navy-light), var(--navy));
  text-align: center;
  position: relative;
  overflow: hidden;
}

.newsletter::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(circle at 30% 30%, rgba(201, 169, 98, 0.1) 0%, transparent 50%);
}

.newsletter-content {
  position: relative;
  z-index: 1;
}

.newsletter h2 {
  color: var(--white);
  margin-bottom: var(--space-md);
}

.newsletter p {
  color: var(--gray-300);
  max-width: 500px;
  margin: 0 auto var(--space-xl);
}

.newsletter-form {
  display: flex;
  gap: var(--space-md);
  max-width: 500px;
  margin: 0 auto;
}

.newsletter-input {
  flex: 1;
  padding: var(--space-md) var(--space-lg);
  background-color: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 4px;
  color: var(--white);
  font-size: 1rem;
}

.newsletter-input::placeholder {
  color: var(--gray-400);
}

.newsletter-input:focus {
  outline: none;
  border-color: var(--gold);
}

/* ===== Latest Insights ===== */
.latest-insights {
  background-color: var(--white);
}

.latest-insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
  margin-top: var(--space-2xl);
}

.latest-insight-card {
  background-color: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  overflow: hidden;
  transition: all var(--transition-base);
}

.latest-insight-card:hover {
  border-color: var(--gold);
  box-shadow: var(--shadow-md);
}

.latest-insight-card-image {
  height: 180px;
  background-color: var(--gray-200);
  background-size: cover;
  background-position: center;
  position: relative;
}

.latest-insight-card-image .insight-card-tag {
  background-color: var(--gold);
  color: var(--navy);
}

.latest-insight-card-content {
  padding: var(--space-lg);
}

.latest-insight-card-meta {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  margin-bottom: var(--space-sm);
}

.latest-insight-card-type {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--teal);
}

.latest-insight-card-date {
  font-size: 0.75rem;
  color: var(--gray-500);
}

.latest-insight-card h4 {
  font-family: var(--font-primary);
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--navy);
  line-height: 1.4;
  margin-bottom: var(--space-md);
}

.latest-insight-card:hover h4 {
  color: var(--teal);
}

/* ===== Our Commitment ===== */
.our-commitment {
  background-color: var(--gray-50);
}

.our-commitment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-lg);
  margin-top: var(--space-2xl);
}

.commitment-card {
  background-color: var(--white);
  border-radius: 8px;
  padding: var(--space-xl);
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
}

.commitment-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.commitment-card-icon {
  width: 56px;
  height: 56px;
  background: linear-gradient(135deg, var(--navy), var(--navy-light));
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-lg);
}

.commitment-card-icon svg {
  width: 28px;
  height: 28px;
  color: var(--gold);
}

.commitment-card h4 {
  font-family: var(--font-primary);
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: var(--space-sm);
}

.commitment-card p {
  font-size: 0.875rem;
  color: var(--gray-600);
  margin-bottom: var(--space-md);
  line-height: 1.6;
}

/* ===== Services Page ===== */
.services-overview {
  padding: var(--space-4xl) 0;
}

.services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
  margin-top: var(--space-2xl);
}

.service-card {
  background-color: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  padding: var(--space-xl);
  transition: all var(--transition-base);
}

.service-card:hover {
  border-color: var(--gold);
  box-shadow: var(--shadow-lg);
}

.service-card-icon {
  width: 64px;
  height: 64px;
  background: linear-gradient(135deg, var(--navy), var(--navy-light));
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-lg);
}

.service-card-icon svg {
  width: 32px;
  height: 32px;
  color: var(--gold);
}

.service-card h3 {
  margin-bottom: var(--space-md);
}

.service-card p {
  font-size: 0.9375rem;
  color: var(--gray-600);
  margin-bottom: var(--space-lg);
}

/* ===== Capabilities Grid ===== */
.capabilities-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
  margin-top: var(--space-2xl);
}

.capability-card {
  background-color: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  padding: var(--space-xl);
  transition: all var(--transition-base);
}

.capability-card:hover {
  border-color: var(--teal);
  box-shadow: var(--shadow-md);
}

.capability-card h4 {
  font-family: var(--font-primary);
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: var(--space-sm);
}

.capability-card p {
  font-size: 0.875rem;
  color: var(--gray-600);
  margin-bottom: var(--space-md);
}

/* ===== Featured Partners Carousel ===== */
.featured-partners {
  background-color: var(--gray-50);
  overflow: hidden;
}

.carousel {
  position: relative;
  margin-top: var(--space-2xl);
}

.carousel-track {
  display: flex;
  gap: var(--space-lg);
  transition: transform 0.5s ease;
}

.carousel-slide {
  flex: 0 0 calc(33.333% - var(--space-lg));
  min-width: 300px;
}

.partner-card {
  background-color: var(--white);
  border-radius: 8px;
  padding: var(--space-xl);
  box-shadow: var(--shadow-sm);
  text-align: center;
}

.partner-logo {
  height: 60px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-md);
  color: var(--navy);
  font-weight: 700;
  font-size: 1.25rem;
}

.partner-card h4 {
  font-family: var(--font-primary);
  font-size: 1rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: var(--space-sm);
}

.partner-card p {
  font-size: 0.875rem;
  color: var(--gray-600);
}

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: var(--space-md);
  margin-top: var(--space-xl);
}

.carousel-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background-color: var(--white);
  border: 1px solid var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.carousel-btn:hover {
  background-color: var(--navy);
  border-color: var(--navy);
  color: var(--white);
}

.carousel-btn svg {
  width: 20px;
  height: 20px;
}

/* ===== Testimonial ===== */
.testimonial {
  background-color: var(--navy);
  text-align: center;
}

.testimonial blockquote {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 3vw, 1.75rem);
  color: var(--white);
  max-width: 800px;
  margin: 0 auto var(--space-xl);
  line-height: 1.6;
  font-style: italic;
}

.testimonial cite {
  display: block;
  font-family: var(--font-primary);
  font-style: normal;
  font-size: 1rem;
  color: var(--gold);
}

.testimonial cite strong {
  display: block;
  color: var(--white);
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

/* ===== Deal Flow CTA ===== */
.deal-flow-cta {
  background: linear-gradient(135deg, var(--gold), var(--gold-light));
  text-align: center;
}

.deal-flow-cta h2 {
  color: var(--navy);
  margin-bottom: var(--space-md);
}

.deal-flow-cta p {
  color: var(--navy);
  opacity: 0.8;
  max-width: 600px;
  margin: 0 auto var(--space-xl);
}

.deal-flow-cta .btn {
  background-color: var(--navy);
  color: var(--white);
  border-color: var(--navy);
}

.deal-flow-cta .btn:hover {
  background-color: var(--navy-light);
}

/* ===== Featured Topics Sidebar ===== */
.featured-topics {
  background-color: var(--gray-50);
}

.topics-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
  margin-top: var(--space-md);
}

.topic-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-md) var(--space-lg);
  background-color: var(--white);
  border-radius: 4px;
  font-weight: 500;
  color: var(--navy);
  transition: all var(--transition-fast);
}

.topic-link:hover {
  background-color: var(--navy);
  color: var(--white);
}

.topic-link svg {
  width: 16px;
  height: 16px;
  opacity: 0;
  transform: translateX(-8px);
  transition: all var(--transition-fast);
}

.topic-link:hover svg {
  opacity: 1;
  transform: translateX(0);
}

/* ===== Property Types CTA ===== */
.property-types-cta {
  background-color: var(--white);
}

.property-types-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-md);
  margin-top: var(--space-xl);
}

.property-type-card {
  background-color: var(--gray-50);
  border-radius: 8px;
  padding: var(--space-lg);
  text-align: center;
  transition: all var(--transition-base);
  cursor: pointer;
}

.property-type-card:hover {
  background-color: var(--navy);
  transform: translateY(-4px);
}

.property-type-card:hover svg {
  color: var(--gold);
}

.property-type-card svg {
  width: 40px;
  height: 40px;
  color: var(--navy);
  margin-bottom: var(--space-sm);
  transition: color var(--transition-fast);
}

.property-type-card h5 {
  font-family: var(--font-primary);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--navy);
  transition: color var(--transition-fast);
}

.property-type-card:hover h5 {
  color: var(--white);
}

/* ===== Related Services ===== */
.related-services {
  background-color: var(--gray-50);
}

.related-services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
  margin-top: var(--space-xl);
}

.related-service-card {
  background-color: var(--white);
  border-radius: 8px;
  padding: var(--space-lg);
  display: flex;
  align-items: flex-start;
  gap: var(--space-md);
  transition: all var(--transition-base);
}

.related-service-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.related-service-icon {
  width: 48px;
  height: 48px;
  background-color: var(--navy);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.related-service-icon svg {
  width: 24px;
  height: 24px;
  color: var(--gold);
}

.related-service-content h5 {
  font-family: var(--font-primary);
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: var(--space-xs);
}

.related-service-content p {
  font-size: 0.8125rem;
  color: var(--gray-500);
  margin: 0;
  line-height: 1.5;
}

/* ===== Related Insights ===== */
.related-insights {
  background-color: var(--white);
}

.related-insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
  margin-top: var(--space-xl);
}

/* ===== Design Build Capabilities ===== */
.design-build-capabilities {
  padding: var(--space-4xl) 0;
}

.capability-highlight {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-xl);
  margin-top: var(--space-2xl);
}

.capability-highlight-card {
  background-color: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  padding: var(--space-2xl);
  position: relative;
  overflow: hidden;
}

.capability-highlight-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 4px;
  height: 100%;
  background: linear-gradient(to bottom, var(--gold), var(--teal));
}

.capability-highlight-card h3 {
  margin-bottom: var(--space-md);
}

.capability-highlight-card p {
  color: var(--gray-600);
  margin-bottom: var(--space-lg);
}

/* ===== Partnership Highlight ===== */
.partnership-highlight {
  background-color: var(--gray-50);
  text-align: center;
}

.partnership-highlight-content {
  max-width: 800px;
  margin: 0 auto;
}

.partnership-highlight-icon {
  width: 80px;
  height: 80px;
  background: linear-gradient(135deg, var(--navy), var(--navy-light));
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-xl);
}

.partnership-highlight-icon svg {
  width: 40px;
  height: 40px;
  color: var(--gold);
}

.partnership-highlight h2 {
  margin-bottom: var(--space-lg);
}

.partnership-highlight p {
  font-size: 1.125rem;
  color: var(--gray-600);
  margin-bottom: var(--space-md);
}

.partnership-stats {
  display: flex;
  justify-content: center;
  gap: var(--space-3xl);
  margin-top: var(--space-xl);
}

.partnership-stat {
  text-align: center;
}

.partnership-stat-value {
  font-family: var(--font-serif);
  font-size: 3rem;
  font-weight: 700;
  color: var(--navy);
  line-height: 1;
}

.partnership-stat-label {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-top: var(--space-xs);
}

/* ===== Footer ===== */
.footer {
  background-color: var(--navy);
  color: var(--white);
  padding: var(--space-4xl) 0 var(--space-xl);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: var(--space-2xl);
  margin-bottom: var(--space-3xl);
}

.footer-brand p {
  color: var(--gray-400);
  font-size: 0.875rem;
  max-width: 300px;
  margin-top: var(--space-lg);
}

.footer-col h5 {
  font-family: var(--font-primary);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray-400);
  margin-bottom: var(--space-lg);
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.footer-col a {
  font-size: 0.875rem;
  color: var(--gray-300);
  transition: color var(--transition-fast);
}

.footer-col a:hover {
  color: var(--gold);
}

.footer-bottom {
  border-top: 1px solid var(--navy-light);
  padding-top: var(--space-xl);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-md);
}

.footer-legal {
  display: flex;
  gap: var(--space-lg);
}

.footer-legal a {
  font-size: 0.8125rem;
  color: var(--gray-400);
}

.footer-legal a:hover {
  color: var(--gold);
}

.footer-copyright {
  font-size: 0.8125rem;
  color: var(--gray-500);
}

/* ===== Utility Classes ===== */
.text-center { text-align: center; }
.text-left { text-align: left; }
.text-right { text-align: right; }

.mt-sm { margin-top: var(--space-sm); }
.mt-md { margin-top: var(--space-md); }
.mt-lg { margin-top: var(--space-lg); }
.mt-xl { margin-top: var(--space-xl); }
.mt-2xl { margin-top: var(--space-2xl); }

.mb-sm { margin-bottom: var(--space-sm); }
.mb-md { margin-bottom: var(--space-md); }
.mb-lg { margin-bottom: var(--space-lg); }
.mb-xl { margin-bottom: var(--space-xl); }
.mb-2xl { margin-bottom: var(--space-2xl); }

.bg-navy { background-color: var(--navy); }
.bg-gray { background-color: var(--gray-50); }
.bg-white { background-color: var(--white); }

.text-white { color: var(--white); }
.text-gold { color: var(--gold); }
.text-teal { color: var(--teal); }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-6 { grid-template-columns: repeat(3, 1fr); }

  .services-grid { grid-template-columns: repeat(2, 1fr); }
  .capabilities-grid { grid-template-columns: repeat(2, 1fr); }
  .our-commitment-grid { grid-template-columns: repeat(2, 1fr); }
  .property-types-grid { grid-template-columns: repeat(3, 1fr); }

  .footer-grid { grid-template-columns: repeat(3, 1fr); }

  .mega-menu-inner { grid-template-columns: 1fr; }
  .mega-menu-links { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .nav-desktop { display: none; }
  .nav-toggle { display: flex; }

  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }

  .featured-insights-grid { grid-template-columns: 1fr; }
  .latest-insights-grid { grid-template-columns: 1fr; }
  .services-grid { grid-template-columns: 1fr; }
  .capabilities-grid { grid-template-columns: 1fr; }
  .our-commitment-grid { grid-template-columns: 1fr; }
  .property-types-grid { grid-template-columns: repeat(2, 1fr); }
  .related-services-grid { grid-template-columns: 1fr; }
  .related-insights-grid { grid-template-columns: 1fr; }
  .capability-highlight { grid-template-columns: 1fr; }

  .what-we-do-tabs {
    grid-template-columns: 1fr;
  }

  .what-we-do-tab-list {
    flex-direction: row;
    overflow-x: auto;
    gap: var(--space-sm);
    padding-bottom: var(--space-md);
  }

  .what-we-do-tab-btn {
    flex-shrink: 0;
    border-left: none;
    border-bottom: 3px solid transparent;
  }

  .what-we-do-tab-btn.active {
    border-left: none;
    border-bottom-color: var(--gold);
  }

  .newsletter-form { flex-direction: column; }

  .partnership-stats {
    flex-direction: column;
    gap: var(--space-xl);
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: var(--space-xl);
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }

  .footer-legal {
    flex-wrap: wrap;
    justify-content: center;
  }

  .hero { min-height: 70vh; }
  .hero-page { min-height: 40vh; }
}

@media (max-width: 480px) {
  .container { padding: 0 var(--space-md); }
  .section { padding: var(--space-2xl) 0; }
  .property-types-grid { grid-template-columns: 1fr; }
}

raw_arguments.content:
/* GlobalStone Corporate Website Styles */

/* ===== CSS Variables ===== */
:root {
  /* Colors */
  --navy: #0A1628;
  --navy-light: #162744;
  --white: #ffffff;
  --gray-50: #F8F9FA;
  --gray-100: #E9ECEF;
  --gray-200: #DEE2E6;
  --gray-300: #CED4DA;
  --gray-400: #ADB5BD;
  --gray-500: #6C757D;
  --gray-600: #495057;
  --gray-700: #343A40;
  --gold: #C9A962;
  --gold-light: #D4B978;
  --teal: #0D7377;
  --teal-light: #14919B;

  /* Typography */
  --font-primary: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-serif: 'Playfair Display', Georgia, serif;

  /* Spacing */
  --space-xs: 0.25rem;
  --space-sm: 0.5rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;
  --space-2xl: 3rem;
  --space-3xl: 4rem;
  --space-4xl: 6rem;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(10, 22, 40, 0.05);
  --shadow-md: 0 4px 12px rgba(10, 22, 40, 0.1);
  --shadow-lg: 0 8px 24px rgba(10, 22, 40, 0.12);
  --shadow-xl: 0 16px 48px rgba(10, 22, 40, 0.15);
}

/* ===== Reset & Base ===== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-primary);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--gray-700);
  background-color: var(--white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* ===== Typography ===== */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 600;
  line-height: 1.2;
  color: var(--navy);
}

h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.75rem); }
h3 { font-size: clamp(1.25rem, 3vw, 1.75rem); }
h4 { font-size: 1.25rem; }
h5 { font-size: 1.125rem; }
h6 { font-size: 1rem; }

p {
  margin-bottom: var(--space-md);
}

.text-serif {
  font-family: var(--font-serif);
}

/* ===== Layout ===== */
.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.container-narrow {
  max-width: 960px;
}

.container-wide {
  max-width: 1440px;
}

.section {
  padding: var(--space-4xl) 0;
}

.section-sm {
  padding: var(--space-2xl) 0;
}

.section-lg {
  padding: var(--space-4xl) 0;
}

/* ===== Grid System ===== */
.grid {
  display: grid;
  gap: var(--space-lg);
}

.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }
.grid-6 { grid-template-columns: repeat(6, 1fr); }

/* ===== Buttons ===== */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: 0.75rem 1.5rem;
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  border-radius: 4px;
  transition: all var(--transition-base);
  cursor: pointer;
}

.btn-primary {
  background-color: var(--navy);
  color: var(--white);
  border: 2px solid var(--navy);
}

.btn-primary:hover {
  background-color: var(--navy-light);
  border-color: var(--navy-light);
}

.btn-secondary {
  background-color: transparent;
  color: var(--navy);
  border: 2px solid var(--navy);
}

.btn-secondary:hover {
  background-color: var(--navy);
  color: var(--white);
}

.btn-gold {
  background-color: var(--gold);
  color: var(--navy);
  border: 2px solid var(--gold);
}

.btn-gold:hover {
  background-color: var(--gold-light);
  border-color: var(--gold-light);
}

.btn-text {
  background: none;
  color: var(--navy);
  padding: 0;
  text-transform: none;
  font-weight: 500;
  text-decoration: underline;
  text-underline-offset: 4px;
}

.btn-text:hover {
  color: var(--teal);
}

.btn-text-white {
  color: var(--white);
}

.btn-text-white:hover {
  color: var(--gold);
}

/* ===== Header & Navigation ===== */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background-color: var(--navy);
  transition: background-color var(--transition-base), box-shadow var(--transition-base);
}

.header.scrolled {
  background-color: rgba(10, 22, 40, 0.98);
  box-shadow: var(--shadow-lg);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-md) var(--space-lg);
  max-width: 1440px;
  margin: 0 auto;
}

.logo {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  color: var(--white);
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.logo-icon {
  width: 40px;
  height: 40px;
  background: linear-gradient(135deg, var(--gold), var(--gold-light));
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--navy);
  font-weight: 900;
  font-size: 1.25rem;
}

/* Desktop Navigation */
.nav-desktop {
  display: flex;
  align-items: center;
  gap: var(--space-xl);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
}

.nav-link {
  color: var(--white);
  font-size: 0.875rem;
  font-weight: 500;
  padding: var(--space-sm) 0;
  position: relative;
  transition: color var(--transition-fast);
}

.nav-link:hover {
  color: var(--gold);
}

.nav-link.active {
  color: var(--gold);
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background-color: var(--gold);
  transition: width var(--transition-base);
}

.nav-link:hover::after,
.nav-link.active::after {
  width: 100%;
}

/* Mega Menu */
.nav-item-dropdown {
  position: static;
}

.nav-item-dropdown .nav-link {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
}

.nav-item-dropdown .nav-link::after {
  content: '';
  display: none;
}

.nav-item-dropdown .nav-link svg {
  width: 12px;
  height: 12px;
  transition: transform var(--transition-fast);
}

.nav-item-dropdown:hover .nav-link svg {
  transform: rotate(180deg);
}

/* Mega Menu Dropdown */
.mega-menu {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background-color: var(--white);
  box-shadow: var(--shadow-xl);
  opacity: 0;
  visibility: hidden;
  transform: translateY(10px);
  transition: all var(--transition-base);
  z-index: 100;
  padding: var(--space-2xl);
}

.nav-item-dropdown:hover .mega-menu {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.mega-menu-inner {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: var(--space-3xl);
  max-width: 1280px;
  margin: 0 auto;
}

.mega-menu-section h4 {
  font-family: var(--font-primary);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray-500);
  margin-bottom: var(--space-md);
}

.mega-menu-links {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-md);
}

.mega-menu-link {
  display: flex;
  align-items: flex-start;
  gap: var(--space-sm);
  padding: var(--space-sm);
  border-radius: 4px;
  transition: background-color var(--transition-fast);
}

.mega-menu-link:hover {
  background-color: var(--gray-50);
}

.mega-menu-link-icon {
  width: 32px;
  height: 32px;
  background-color: var(--navy);
  color: var(--white);
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.mega-menu-link-text h5 {
  font-family: var(--font-primary);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 2px;
}

.mega-menu-link-text p {
  font-size: 0.75rem;
  color: var(--gray-500);
  margin: 0;
  line-height: 1.4;
}

.mega-menu-cta {
  background-color: var(--gray-50);
  padding: var(--space-lg);
  border-radius: 8px;
  text-align: center;
}

.mega-menu-cta h5 {
  font-family: var(--font-primary);
  font-size: 1rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: var(--space-sm);
}

.mega-menu-cta p {
  font-size: 0.875rem;
  color: var(--gray-600);
  margin-bottom: var(--space-md);
}

/* Mobile Navigation Toggle */
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: var(--space-sm);
  cursor: pointer;
}

.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background-color: var(--white);
  transition: all var(--transition-fast);
}

/* Mobile Navigation */
.nav-mobile {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--navy);
  overflow-y: auto;
  z-index: 999;
}

.nav-mobile.active {
  display: block;
}

.nav-mobile-section {
  border-bottom: 1px solid var(--navy-light);
}

.nav-mobile-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-lg);
  color: var(--white);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
}

.nav-mobile-section-header svg {
  width: 20px;
  height: 20px;
  transition: transform var(--transition-fast);
}

.nav-mobile-section.active .nav-mobile-section-header svg {
  transform: rotate(180deg);
}

.nav-mobile-section-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-base);
}

.nav-mobile-section.active .nav-mobile-section-content {
  max-height: 500px;
}

.nav-mobile-link {
  display: block;
  padding: var(--space-md) var(--space-lg);
  padding-left: var(--space-2xl);
  color: var(--gray-300);
  font-size: 0.875rem;
  transition: color var(--transition-fast);
}

.nav-mobile-link:hover {
  color: var(--gold);
}

/* ===== Hero Section ===== */
.hero {
  position: relative;
  min-height: 80vh;
  display: flex;
  align-items: center;
  background-color: var(--navy);
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-light) 100%);
}

.hero-bg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><defs><pattern id="grid" width="10" height="10" patternUnits="userSpaceOnUse"><path d="M 10 0 L 0 0 0 10" fill="none" stroke="rgba(255,255,255,0.03)" stroke-width="0.5"/></pattern></defs><rect fill="url(%23grid)" width="100" height="100"/></svg>');
  opacity: 0.5;
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 800px;
  padding: var(--space-4xl) var(--space-lg);
}

.hero-badge {
  display: inline-block;
  background-color: rgba(201, 169, 98, 0.2);
  color: var(--gold);
  padding: var(--space-xs) var(--space-md);
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: var(--space-lg);
}

.hero h1 {
  color: var(--white);
  margin-bottom: var(--space-lg);
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--gray-300);
  margin-bottom: var(--space-xl);
  max-width: 600px;
}

.hero-actions {
  display: flex;
  gap: var(--space-md);
  flex-wrap: wrap;
}

/* Hero - Page Header Variant */
.hero-page {
  min-height: 50vh;
  text-align: center;
}

.hero-page .hero-content {
  max-width: 900px;
  margin: 0 auto;
}

/* ===== Featured Insights ===== */
.featured-insights {
  background-color: var(--gray-50);
}

.featured-insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
  margin-top: var(--space-2xl);
}

.insight-card {
  background-color: var(--white);
  border-radius: 8px;
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
}

.insight-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.insight-card-image {
  height: 160px;
  background-color: var(--gray-200);
  background-size: cover;
  background-position: center;
  position: relative;
}

.insight-card-image::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, transparent 50%, rgba(10, 22, 40, 0.3));
}

.insight-card-tag {
  position: absolute;
  top: var(--space-md);
  left: var(--space-md);
  background-color: var(--navy);
  color: var(--white);
  padding: var(--space-xs) var(--space-sm);
  font-size: 0.625rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-radius: 2px;
}

.insight-card-content {
  padding: var(--space-lg);
}

.insight-card-type {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: var(--space-sm);
}

.insight-card-title {
  font-family: var(--font-primary);
  font-size: 1rem;
  font-weight: 600;
  color: var(--navy);
  line-height: 1.4;
  margin-bottom: var(--space-sm);
}

.insight-card:hover .insight-card-title {
  color: var(--teal);
}

.insight-card-link {
  display: inline-flex;
  align-items: center;
  gap: var(--space-xs);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--navy);
}

.insight-card-link svg {
  width: 16px;
  height: 16px;
  transition: transform var(--transition-fast);
}

.insight-card:hover .insight-card-link svg {
  transform: translateX(4px);
}

/* ===== Announcement Banner ===== */
.announcement-banner {
  background: linear-gradient(135deg, var(--teal), var(--teal-light));
  padding: var(--space-lg) 0;
  text-align: center;
}

.announcement-banner p {
  color: var(--white);
  font-size: 1rem;
  margin-bottom: var(--space-md);
}

.announcement-banner .btn {
  background-color: var(--white);
  color: var(--teal);
  border-color: var(--white);
}

.announcement-banner .btn:hover {
  background-color: var(--gold);
  border-color: var(--gold);
  color: var(--navy);
}

/* ===== About Statement ===== */
.about-statement {
  background-color: var(--white);
  text-align: center;
}

.about-statement h2 {
  margin-bottom: var(--space-lg);
}

.about-statement p {
  max-width: 800px;
  margin: 0 auto var(--space-xl);
  font-size: 1.125rem;
  color: var(--gray-600);
}

/* ===== What We Do Tabs ===== */
.what-we-do {
  background-color: var(--navy);
}

.what-we-do .section-header {
  text-align: center;
  margin-bottom: var(--space-2xl);
}

.what-we-do .section-header h2 {
  color: var(--white);
}

.what-we-do-tabs {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: var(--space-2xl);
  max-width: 1000px;
  margin: 0 auto;
}

.what-we-do-tab-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.what-we-do-tab-btn {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  padding: var(--space-md) var(--space-lg);
  background: none;
  border: none;
  border-left: 3px solid transparent;
  color: var(--gray-400);
  font-size: 1rem;
  font-weight: 500;
  text-align: left;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.what-we-do-tab-btn:hover {
  color: var(--white);
}

.what-we-do-tab-btn.active {
  background-color: rgba(255, 255, 255, 0.05);
  border-left-color: var(--gold);
  color: var(--white);
}

.what-we-do-tab-btn svg {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
}

.what-we-do-tab-content {
  background-color: rgba(255, 255, 255, 0.05);
  border-radius: 8px;
  padding: var(--space-2xl);
  display: none;
}

.what-we-do-tab-content.active {
  display: block;
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.what-we-do-tab-content h3 {
  color: var(--white);
  margin-bottom: var(--space-md);
}

.what-we-do-tab-content p {
  color: var(--gray-300);
  margin-bottom: var(--space-lg);
  line-height: 1.7;
}

.what-we-do-tab-content .btn {
  margin-top: var(--space-md);
}

/* ===== Newsletter Section ===== */
.newsletter {
  background: linear-gradient(135deg, var(--navy-light), var(--navy));
  text-align: center;
  position: relative;
  overflow: hidden;
}

.newsletter::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(circle at 30% 30%, rgba(201, 169, 98, 0.1) 0%, transparent 50%);
}

.newsletter-content {
  position: relative;
  z-index: 1;
}

.newsletter h2 {
  color: var(--white);
  margin-bottom: var(--space-md);
}

.newsletter p {
  color: var(--gray-300);
  max-width: 500px;
  margin: 0 auto var(--space-xl);
}

.newsletter-form {
  display: flex;
  gap: var(--space-md);
  max-width: 500px;
  margin: 0 auto;
}

.newsletter-input {
  flex: 1;
  padding: var(--space-md) var(--space-lg);
  background-color: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 4px;
  color: var(--white);
  font-size: 1rem;
}

.newsletter-input::placeholder {
  color: var(--gray-400);
}

.newsletter-input:focus {
  outline: none;
  border-color: var(--gold);
}

/* ===== Latest Insights ===== */
.latest-insights {
  background-color: var(--white);
}

.latest-insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
  margin-top: var(--space-2xl);
}

.latest-insight-card {
  background-color: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  overflow: hidden;
  transition: all var(--transition-base);
}

.latest-insight-card:hover {
  border-color: var(--gold);
  box-shadow: var(--shadow-md);
}

.latest-insight-card-image {
  height: 180px;
  background-color: var(--gray-200);
  background-size: cover;
  background-position: center;
  position: relative;
}

.latest-insight-card-image .insight-card-tag {
  background-color: var(--gold);
  color: var(--navy);
}

.latest-insight-card-content {
  padding: var(--space-lg);
}

.latest-insight-card-meta {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  margin-bottom: var(--space-sm);
}

.latest-insight-card-type {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--teal);
}

.latest-insight-card-date {
  font-size: 0.75rem;
  color: var(--gray-500);
}

.latest-insight-card h4 {
  font-family: var(--font-primary);
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--navy);
  line-height: 1.4;
  margin-bottom: var(--space-md);
}

.latest-insight-card:hover h4 {
  color: var(--teal);
}

/* ===== Our Commitment ===== */
.our-commitment {
  background-color: var(--gray-50);
}

.our-commitment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-lg);
  margin-top: var(--space-2xl);
}

.commitment-card {
  background-color: var(--white);
  border-radius: 8px;
  padding: var(--space-xl);
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
}

.commitment-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.commitment-card-icon {
  width: 56px;
  height: 56px;
  background: linear-gradient(135deg, var(--navy), var(--navy-light));
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-lg);
}

.commitment-card-icon svg {
  width: 28px;
  height: 28px;
  color: var(--gold);
}

.commitment-card h4 {
  font-family: var(--font-primary);
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: var(--space-sm);
}

.commitment-card p {
  font-size: 0.875rem;
  color: var(--gray-600);
  margin-bottom: var(--space-md);
  line-height: 1.6;
}

/* ===== Services Page ===== */
.services-overview {
  padding: var(--space-4xl) 0;
}

.services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-xl);
  margin-top: var(--space-2xl);
}

.service-card {
  background-color: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  padding: var(--space-xl);
  transition: all var(--transition-base);
}

.service-card:hover {
  border-color: var(--gold);
  box-shadow: var(--shadow-lg);
}

.service-card-icon {
  width: 64px;
  height: 64px;
  background: linear-gradient(135deg, var(--navy), var(--navy-light));
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-lg);
}

.service-card-icon svg {
  width: 32px;
  height: 32px;
  color: var(--gold);
}

.service-card h3 {
  margin-bottom: var(--space-md);
}

.service-card p {
  font-size: 0.9375rem;
  color: var(--gray-600);
  margin-bottom: var(--space-lg);
}

/* ===== Capabilities Grid ===== */
.capabilities-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
  margin-top: var(--space-2xl);
}

.capability-card {
  background-color: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  padding: var(--space-xl);
  transition: all var(--transition-base);
}

.capability-card:hover {
  border-color: var(--teal);
  box-shadow: var(--shadow-md);
}

.capability-card h4 {
  font-family: var(--font-primary);
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: var(--space-sm);
}

.capability-card p {
  font-size: 0.875rem;
  color: var(--gray-600);
  margin-bottom: var(--space-md);
}

/* ===== Featured Partners Carousel ===== */
.featured-partners {
  background-color: var(--gray-50);
  overflow: hidden;
}

.carousel {
  position: relative;
  margin-top: var(--space-2xl);
}

.carousel-track {
  display: flex;
  gap: var(--space-lg);
  transition: transform 0.5s ease;
}

.carousel-slide {
  flex: 0 0 calc(33.333% - var(--space-lg));
  min-width: 300px;
}

.partner-card {
  background-color: var(--white);
  border-radius: 8px;
  padding: var(--space-xl);
  box-shadow: var(--shadow-sm);
  text-align: center;
}

.partner-logo {
  height: 60px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: var(--space-md);
  color: var(--navy);
  font-weight: 700;
  font-size: 1.25rem;
}

.partner-card h4 {
  font-family: var(--font-primary);
  font-size: 1rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: var(--space-sm);
}

.partner-card p {
  font-size: 0.875rem;
  color: var(--gray-600);
}

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: var(--space-md);
  margin-top: var(--space-xl);
}

.carousel-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background-color: var(--white);
  border: 1px solid var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.carousel-btn:hover {
  background-color: var(--navy);
  border-color: var(--navy);
  color: var(--white);
}

.carousel-btn svg {
  width: 20px;
  height: 20px;
}

/* ===== Testimonial ===== */
.testimonial {
  background-color: var(--navy);
  text-align: center;
}

.testimonial blockquote {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 3vw, 1.75rem);
  color: var(--white);
  max-width: 800px;
  margin: 0 auto var(--space-xl);
  line-height: 1.6;
  font-style: italic;
}

.testimonial cite {
  display: block;
  font-family: var(--font-primary);
  font-style: normal;
  font-size: 1rem;
  color: var(--gold);
}

.testimonial cite strong {
  display: block;
  color: var(--white);
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

/* ===== Deal Flow CTA ===== */
.deal-flow-cta {
  background: linear-gradient(135deg, var(--gold), var(--gold-light));
  text-align: center;
}

.deal-flow-cta h2 {
  color: var(--navy);
  margin-bottom: var(--space-md);
}

.deal-flow-cta p {
  color: var(--navy);
  opacity: 0.8;
  max-width: 600px;
  margin: 0 auto var(--space-xl);
}

.deal-flow-cta .btn {
  background-color: var(--navy);
  color: var(--white);
  border-color: var(--navy);
}

.deal-flow-cta .btn:hover {
  background-color: var(--navy-light);
}

/* ===== Featured Topics Sidebar ===== */
.featured-topics {
  background-color: var(--gray-50);
}

.topics-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
  margin-top: var(--space-md);
}

.topic-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-md) var(--space-lg);
  background-color: var(--white);
  border-radius: 4px;
  font-weight: 500;
  color: var(--navy);
  transition: all var(--transition-fast);
}

.topic-link:hover {
  background-color: var(--navy);
  color: var(--white);
}

.topic-link svg {
  width: 16px;
  height: 16px;
  opacity: 0;
  transform: translateX(-8px);
  transition: all var(--transition-fast);
}

.topic-link:hover svg {
  opacity: 1;
  transform: translateX(0);
}

/* ===== Property Types CTA ===== */
.property-types-cta {
  background-color: var(--white);
}

.property-types-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-md);
  margin-top: var(--space-xl);
}

.property-type-card {
  background-color: var(--gray-50);
  border-radius: 8px;
  padding: var(--space-lg);
  text-align: center;
  transition: all var(--transition-base);
  cursor: pointer;
}

.property-type-card:hover {
  background-color: var(--navy);
  transform: translateY(-4px);
}

.property-type-card:hover svg {
  color: var(--gold);
}

.property-type-card svg {
  width: 40px;
  height: 40px;
  color: var(--navy);
  margin-bottom: var(--space-sm);
  transition: color var(--transition-fast);
}

.property-type-card h5 {
  font-family: var(--font-primary);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--navy);
  transition: color var(--transition-fast);
}

.property-type-card:hover h5 {
  color: var(--white);
}

/* ===== Related Services ===== */
.related-services {
  background-color: var(--gray-50);
}

.related-services-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
  margin-top: var(--space-xl);
}

.related-service-card {
  background-color: var(--white);
  border-radius: 8px;
  padding: var(--space-lg);
  display: flex;
  align-items: flex-start;
  gap: var(--space-md);
  transition: all var(--transition-base);
}

.related-service-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.related-service-icon {
  width: 48px;
  height: 48px;
  background-color: var(--navy);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.related-service-icon svg {
  width: 24px;
  height: 24px;
  color: var(--gold);
}

.related-service-content h5 {
  font-family: var(--font-primary);
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: var(--space-xs);
}

.related-service-content p {
  font-size: 0.8125rem;
  color: var(--gray-500);
  margin: 0;
  line-height: 1.5;
}

/* ===== Related Insights ===== */
.related-insights {
  background-color: var(--white);
}

.related-insights-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
  margin-top: var(--space-xl);
}

/* ===== Design Build Capabilities ===== */
.design-build-capabilities {
  padding: var(--space-4xl) 0;
}

.capability-highlight {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-xl);
  margin-top: var(--space-2xl);
}

.capability-highlight-card {
  background-color: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: 8px;
  padding: var(--space-2xl);
  position: relative;
  overflow: hidden;
}

.capability-highlight-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 4px;
  height: 100%;
  background: linear-gradient(to bottom, var(--gold), var(--teal));
}

.capability-highlight-card h3 {
  margin-bottom: var(--space-md);
}

.capability-highlight-card p {
  color: var(--gray-600);
  margin-bottom: var(--space-lg);
}

/* ===== Partnership Highlight ===== */
.partnership-highlight {
  background-color: var(--gray-50);
  text-align: center;
}

.partnership-highlight-content {
  max-width: 800px;
  margin: 0 auto;
}

.partnership-highlight-icon {
  width: 80px;
  height: 80px;
  background: linear-gradient(135deg, var(--navy), var(--navy-light));
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto var(--space-xl);
}

.partnership-highlight-icon svg {
  width: 40px;
  height: 40px;
  color: var(--gold);
}

.partnership-highlight h2 {
  margin-bottom: var(--space-lg);
}

.partnership-highlight p {
  font-size: 1.125rem;
  color: var(--gray-600);
  margin-bottom: var(--space-md);
}

.partnership-stats {
  display: flex;
  justify-content: center;
  gap: var(--space-3xl);
  margin-top: var(--space-xl);
}

.partnership-stat {
  text-align: center;
}

.partnership-stat-value {
  font-family: var(--font-serif);
  font-size: 3rem;
  font-weight: 700;
  color: var(--navy);
  line-height: 1;
}

.partnership-stat-label {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-top: var(--space-xs);
}

/* ===== Footer ===== */
.footer {
  background-color: var(--navy);
  color: var(--white);
  padding: var(--space-4xl) 0 var(--space-xl);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: var(--space-2xl);
  margin-bottom: var(--space-3xl);
}

.footer-brand p {
  color: var(--gray-400);
  font-size: 0.875rem;
  max-width: 300px;
  margin-top: var(--space-lg);
}

.footer-col h5 {
  font-family: var(--font-primary);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray-400);
  margin-bottom: var(--space-lg);
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.footer-col a {
  font-size: 0.875rem;
  color: var(--gray-300);
  transition: color var(--transition-fast);
}

.footer-col a:hover {
  color: var(--gold);
}

.footer-bottom {
  border-top: 1px solid var(--navy-light);
  padding-top: var(--space-xl);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-md);
}

.footer-legal {
  display: flex;
  gap: var(--space-lg);
}

.footer-legal a {
  font-size: 0.8125rem;
  color: var(--gray-400);
}

.footer-legal a:hover {
  color: var(--gold);
}

.footer-copyright {
  font-size: 0.8125rem;
  color: var(--gray-500);
}

/* ===== Utility Classes ===== */
.text-center { text-align: center; }
.text-left { text-align: left; }
.text-right { text-align: right; }

.mt-sm { margin-top: var(--space-sm); }
.mt-md { margin-top: var(--space-md); }
.mt-lg { margin-top: var(--space-lg); }
.mt-xl { margin-top: var(--space-xl); }
.mt-2xl { margin-top: var(--space-2xl); }

.mb-sm { margin-bottom: var(--space-sm); }
.mb-md { margin-bottom: var(--space-md); }
.mb-lg { margin-bottom: var(--space-lg); }
.mb-xl { margin-bottom: var(--space-xl); }
.mb-2xl { margin-bottom: var(--space-2xl); }

.bg-navy { background-color: var(--navy); }
.bg-gray { background-color: var(--gray-50); }
.bg-white { background-color: var(--white); }

.text-white { color: var(--white); }
.text-gold { color: var(--gold); }
.text-teal { color: var(--teal); }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-6 { grid-template-columns: repeat(3, 1fr); }

  .services-grid { grid-template-columns: repeat(2, 1fr); }
  .capabilities-grid { grid-template-columns: repeat(2, 1fr); }
  .our-commitment-grid { grid-template-columns: repeat(2, 1fr); }
  .property-types-grid { grid-template-columns: repeat(3, 1fr); }

  .footer-grid { grid-template-columns: repeat(3, 1fr); }

  .mega-menu-inner { grid-template-columns: 1fr; }
  .mega-menu-links { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .nav-desktop { display: none; }
  .nav-toggle { display: flex; }

  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }

  .featured-insights-grid { grid-template-columns: 1fr; }
  .latest-insights-grid { grid-template-columns: 1fr; }
  .services-grid { grid-template-columns: 1fr; }
  .capabilities-grid { grid-template-columns: 1fr; }
  .our-commitment-grid { grid-template-columns: 1fr; }
  .property-types-grid { grid-template-columns: repeat(2, 1fr); }
  .related-services-grid { grid-template-columns: 1fr; }
  .related-insights-grid { grid-template-columns: 1fr; }
  .capability-highlight { grid-template-columns: 1fr; }

  .what-we-do-tabs {
    grid-template-columns: 1fr;
  }

  .what-we-do-tab-list {
    flex-direction: row;
    overflow-x: auto;
    gap: var(--space-sm);
    padding-bottom: var(--space-md);
  }

  .what-we-do-tab-btn {
    flex-shrink: 0;
    border-left: none;
    border-bottom: 3px solid transparent;
  }

  .what-we-do-tab-btn.active {
    border-left: none;
    border-bottom-color: var(--gold);
  }

  .newsletter-form { flex-direction: column; }

  .partnership-stats {
    flex-direction: column;
    gap: var(--space-xl);
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: var(--space-xl);
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }

  .footer-legal {
    flex-wrap: wrap;
    justify-content: center;
  }

  .hero { min-height: 70vh; }
  .hero-page { min-height: 40vh; }
}

@media (max-width: 480px) {
  .container { padding: 0 var(--space-md); }
  .section { padding: var(--space-2xl) 0; }
  .property-types-grid { grid-template-columns: 1fr; }
}
